  'Planificar líneas o cuadrícula aquí': {en: 'Plan lines or a grid here', fr: 'Planifier des lignes ou une grille ici', pt: 'Planejar linhas ou grade aqui'},
  'Recorrer el borde': {en: 'Walk the boundary', fr: 'Suivre le contour', pt: 'Percorrer o contorno'},
  'Editar este elemento': {en: 'Edit this feature', fr: 'Modifier cette entité', pt: 'Editar esta feição'},
  'Atributos': {en: 'Attributes', fr: 'Attributs', pt: 'Atributos'},
  'Elemento': {en: 'Feature', fr: 'Entité', pt: 'Feição'},
  'Este elemento tiene {n} parte: se planifica en la más grande.': {en: 'This feature has {n} part: the plan uses the largest one.', fr: 'Cette entité a {n} partie : le plan utilise la plus grande.', pt: 'Esta feição tem {n} parte: o plano usa a maior.'},
  'Este elemento tiene {n} partes: se planifica en la más grande.': {en: 'This feature has {n} parts: the plan uses the largest one.', fr: 'Cette entité a {n} parties : le plan utilise la plus grande.', pt: 'Esta feição tem {n} partes: o plano usa a maior.'},
  'Punto en el mapa': {en: 'Point on the map', fr: 'Point sur la carte', pt: 'Ponto no mapa'},
  'Guardar en Mis puntos': {en: 'Save to My points', fr: 'Enregistrer dans Mes points', pt: 'Salvar em Meus pontos'},
  'Guardar punto': {en: 'Save point', fr: 'Enregistrer le point', pt: 'Salvar ponto'},
