  'Por partes (normal)': {en: 'In parts (normal)', fr: 'Par morceaux (normal)', pt: 'Por partes (normal)'},
  'Versión {v}': {en: 'Version {v}', fr: 'Version {v}', pt: 'Versão {v}'},
  'Mapas de campo que funcionan sin internet: sus propias imágenes, puntos y recorridos, y guía con el GPS para seguir líneas y llegar a puntos.': {en: 'Field maps that work without internet: your own images, points and tracks, plus GPS guidance to follow lines and reach points.', fr: 'Des cartes de terrain qui fonctionnent sans Internet : vos propres images, points et traces, et un guidage GPS pour suivre des lignes et rejoindre des points.', pt: 'Mapas de campo que funcionam sem internet: suas próprias imagens, pontos e trilhas, e orientação por GPS para seguir linhas e chegar a pontos.'},
  'Ver los textos de las licencias': {en: 'View the license texts', fr: 'Voir les textes des licences', pt: 'Ver os textos das licenças'},
  'Información técnica': {en: 'Technical information', fr: 'Informations techniques', pt: 'Informações técnicas'},
  'Lectura de imágenes grandes': {en: 'Reading large images', fr: 'Lecture des grandes images', pt: 'Leitura de imagens grandes'},
  'Dibujo de imágenes': {en: 'Image drawing', fr: 'Affichage des images', pt: 'Desenho de imagens'},
